"""Engine wrapper: the authors' fastText trainer.

The paper's system *is* the facebookresearch/fastText C++ supervised trainer, so this
module forwards every hyperparameter verbatim to it.  Resolution order:

  1. an already-importable `fasttext` module (native build, wheel, or conda package);
  2. `pip install fasttext-wheel` -- a prebuilt binary wheel of the same
     facebookresearch/fastText C++ code (0.9.2) plus the official Python binding;
  3. a native build from the cloned repo (`pip install .`, needs a C++ toolchain);
  4. otherwise fail with an explicit message (the host has no compiler and no bash).

No author code is rewritten and no paper number is hard-coded here.
"""
import importlib
import os
import subprocess
import sys
import time

ENGINE_CACHE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "engine_info.json")


def _try_import():
    try:
        ft = importlib.import_module("fasttext")
        return ft, "importable fasttext module"
    except Exception:
        return None, None


def _pip_install(pkg):
    print("[engine] pip install %s" % pkg)
    r = subprocess.run([sys.executable, "-m", "pip", "install", pkg],
                       capture_output=True, text=True)
    print(r.stdout[-2000:])
    if r.returncode != 0:
        print(r.stderr[-2000:])
    importlib.invalidate_caches()
    return r.returncode == 0


def get_engine(repo_dir="repo"):
    ft, prov = _try_import()
    if ft is not None:
        return ft, prov
    if _pip_install("fasttext-wheel"):
        ft, _ = _try_import()
        if ft is not None:
            return ft, "fasttext-wheel (pip)"
    if _pip_install(repo_dir):
        ft, _ = _try_import()
        if ft is not None:
            return ft, "native build from repo (pip install .)"
    raise RuntimeError(
        "No fastText engine available. Tried: existing module, fasttext-wheel, "
        "native build in %r. The host has no make/g++/clang and no bash, so a source "
        "build is not possible here." % repo_dir)


def describe(ft):
    d = {"module_file": getattr(ft, "__file__", "?")}
    try:
        import fasttext
        d["version"] = getattr(ft, "__version__", "(no __version__)")
    except Exception:
        d["version"] = "?"
    try:
        import os as _os
        p = _os.path.dirname(d["module_file"])
        cand = [f for f in _os.listdir(p) if f.endswith((".pyd", ".so"))]
        d["binary"] = cand
    except Exception:
        pass
    return d


def train(ft, input_path, output_path, **kwargs):
    """Train and return (model, train_seconds, used_kwargs)."""
    kw = dict(kwargs)
    kw["input"] = input_path
    kw["output"] = output_path
    t0 = time.time()
    model = ft.train_supervised(**kw)
    dt = time.time() - t0
    return model, dt, kw


def test(model, path):
    n, p1, r1 = model.test(path)
    return {"n": int(n), "p1": float(p1), "r1": float(r1)}


def predict_labels(model, lines, k=1):
    labs, probs = model.predict(lines, k=k)
    return labs, probs

